// Validate and normalise the inquiry before anything else touches it.
// Runs once per incoming item; never trusts the caller's shape.
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const DISPOSABLE = ['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com'];
const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const errors = [];

  const name = String(b.name ?? '').trim();
  const email = String(b.email ?? '').trim().toLowerCase();
  const company = String(b.company ?? '').trim();
  const message = String(b.message ?? b.description ?? '').trim();
  const service = String(b.service ?? '').trim();
  const budget = String(b.budget ?? '').trim();
  const consent = b.consent === true || b.consent === 'true' || b.consent === 'on';

  if (name.length < 2 || name.length > 100) errors.push('name');
  if (!EMAIL.test(email) || email.length > 200) errors.push('email');
  if (message.length < 20 || message.length > 4000) errors.push('message');
  if (!consent) errors.push('consent');
  if (String(b.website ?? '') !== '') errors.push('honeypot');

  const domain = email.split('@')[1] ?? '';
  const disposable = DISPOSABLE.includes(domain);
  const freemail = ['gmail.com', 'outlook.com', 'hotmail.com', 'yahoo.com', 'icloud.com'].includes(domain);

  out.push({
    json: {
      valid: errors.length === 0 && !disposable,
      errors,
      disposable,
      lead: {
        name, email, company, message, service, budget, consent,
        domain,
        freemail,
        receivedAt: new Date().toISOString(),
        // Stable key for duplicate detection: one person, one open thread.
        dedupeKey: email,
        source: String(b.source ?? 'website'),
      },
    },
  });
}

return out;

// Duplicate detection.
// Swap the static-data store for a CRM search in production; the contract
// below (isDuplicate + previousCount) is all the rest of the flow needs.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const out = [];

for (const item of $input.all()) {
  const key = item.json.lead.dedupeKey;
  const prev = store.seen[key];
  const now = Date.now();
  const WINDOW_MS = 30 * 24 * 60 * 60 * 1000;
  const isDuplicate = Boolean(prev && now - prev.lastSeen < WINDOW_MS);

  store.seen[key] = { lastSeen: now, count: (prev?.count ?? 0) + 1 };

  out.push({
    json: {
      ...item.json,
      isDuplicate,
      previousCount: prev?.count ?? 0,
    },
  });
}

return out;

// Transparent lead scoring. Every point is recorded with its reason so a
// human reviewing the lead can see exactly why it scored what it did.
const BUDGET_POINTS = {
  'Under $1,000': 5,
  '$1,000 – $5,000': 18,
  '$5,000 – $15,000': 28,
  '$15,000+': 35,
  'Prefer to discuss': 10,
};
const HIGH_INTENT = /\b(quote|proposal|contract|start|deadline|launch|asap|urgent|budget approved)\b/i;
const LOW_INTENT = /\b(student|thesis|assignment|free|intern|portfolio review|just curious)\b/i;

return $input.all().map((item) => {
  const { lead, isDuplicate, previousCount } = item.json;
  let score = 0;
  const reasons = [];

  const budgetPoints = BUDGET_POINTS[lead.budget] ?? 0;
  if (budgetPoints) { score += budgetPoints; reasons.push(`Budget "${lead.budget}" (+${budgetPoints})`); }

  if (lead.company) { score += 12; reasons.push('Company named (+12)'); }
  if (!lead.freemail && lead.domain) { score += 15; reasons.push(`Business domain ${lead.domain} (+15)`); }
  if (lead.service && lead.service !== 'Not sure yet') { score += 10; reasons.push(`Specific service: ${lead.service} (+10)`); }
  if (lead.message.length > 300) { score += 10; reasons.push('Detailed brief (+10)'); }
  if (HIGH_INTENT.test(lead.message)) { score += 15; reasons.push('High-intent language (+15)'); }
  if (LOW_INTENT.test(lead.message)) { score -= 20; reasons.push('Low-intent language (-20)'); }
  if (isDuplicate) { score -= 10; reasons.push(`Duplicate within 30 days, ${previousCount} previous (-10)`); }

  score = Math.max(0, Math.min(100, score));
  const band = score >= 60 ? 'hot' : score >= 30 ? 'warm' : 'cold';

  return { json: { ...item.json, score, band, reasons } };
});

// Draft a reply for a human to approve. Composed from fixed fragments —
// no model is called, so the wording cannot drift and nothing is invented.
const OPENERS = {
  hot: 'Thanks for getting in touch — this sounds like a good fit and I would like to talk properly.',
  warm: 'Thanks for getting in touch. Happy to help with this.',
  cold: 'Thanks for getting in touch.',
};
const NEXT = {
  hot: 'Are you free for a 20-minute call this week? Send me a couple of times that suit and I will confirm.',
  warm: 'Could you tell me a little more about the timeline and what success would look like?',
  cold: 'If you can share a bit more detail about scope and timing, I will let you know honestly whether I am the right fit.',
};

return $input.all().map((item) => {
  const { lead, band, score, reasons } = item.json;
  const first = lead.name.split(' ')[0];
  const service = lead.service && lead.service !== 'Not sure yet' ? ` about ${lead.service.toLowerCase()}` : '';

  const draft = [
    `Hi ${first},`,
    '',
    `${OPENERS[band]}`,
    '',
    `You wrote${service}:`,
    `"${lead.message.slice(0, 400)}${lead.message.length > 400 ? '…' : ''}"`,
    '',
    NEXT[band],
    '',
    'Best,',
    'Ali',
  ].join('\n');

  return {
    json: {
      ...item.json,
      approval: {
        status: 'pending_human_approval',
        to: lead.email,
        subject: `Re: your enquiry${service}`,
        draft,
        scoreSummary: `${band} (${score}) — ${reasons.join('; ')}`,
      },
    },
  };
});

// Any step that failed lands here with enough context to retry by hand.
return $input.all().map((item) => ({
  json: {
    failedAt: new Date().toISOString(),
    node: item.json?.error?.node ?? 'unknown',
    message: item.json?.error?.message ?? 'Downstream call failed',
    lead: item.json?.lead ?? null,
  },
}));
